        for (c1,i1),(c2,i2) in zip(lst,lst[1:]):
            l,rg=sorted((max(x[1] for x in comps[i1]), min(x[1] for x in comps[i2])))
            for x in range(l+1,rg):
                if out[r][x]==0: out[r][x]=1
    for c,lst in cols.items():
        lst.sort()
        for (r1,i1),(r2,i2) in zip(lst,lst[1:]):
            tp,bt=sorted((max(x[0] for x in comps[i1]), min(x[0] for x in comps[i2])))
            for y in range(tp+1,bt):
                if out[y][c]==0: out[y][c]=1
